def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    A = int(data[0])
    B = int(data[1])

    # We will create a grid of size max(A, B) x max(A, B)
    h = max(A, B)
    w = max(A, B)

    print(h, w)

    # Create the grid
    grid = [['.' for _ in range(w)] for _ in range(h)]

    # Place A white components
    for i in range(A):
        grid[i // w][i % w] = '.'

    # Place B black components
    for i in range(B):
        grid[h - 1 - (i // w)][w - 1 - (i % w)] = '#'

    # Ensure each component is connected
    for i in range(h):
        for j in range(w):
            if grid[i][j] == '.':
                # Find the next empty cell to connect
                for ni in range(i + 1, h):
                    for nj in range(w):
                        if grid[ni][nj] == '.':
                            grid[ni][nj] = '.'
                            break
                    else:
                        continue
                    break

    for i in range(h):
        for j in range(w):
            if grid[i][j] == '#':
                # Find the next empty cell to connect
                for ni in range(i + 1, h):
                    for nj in range(w):
                        if grid[ni][nj] == '#':
                            grid[ni][nj] = '#'
                            break
                    else:
                        continue
                    break

    # Print the grid
    for row in grid:
        print(''.join(row))

if __name__ == "__main__":
    main()
